// BAD: lifting email input state to the page level
function Page() {
  const [email, setEmail] = useState('');
  return <UserForm email={email} onEmailChange={setEmail} />;
}

// GOOD: state stays inside the component that needs it
function EmailField() {
  const [email, setEmail] = useState('');
  return <input value={email} onChange={(e) => setEmail(e.target.value)} />;
}

import { memo } from 'react';

const ExpensiveList = memo(function ExpensiveList({
  items,
}: {
  items: string[];
}) {
  console.log('Rendering list');
  return (
    <ul>
      {items.map((item) => (
        <li key={item}>{item}</li>
      ))}
    </ul>
  );
});

function Dashboard() {
  const [count, setCount] = useState(0);
  const items = ['React', 'Next.js', 'TypeScript'];

  return (
    <div>
      <button onClick={() => setCount((c) => c + 1)}>Count: {count}</button>
      {/* ExpensiveList only re-renders if items changes */}
      <ExpensiveList items={items} />
    </div>
  );
}
